}

function dec(a) {
    var to = this.as(a[2]),
        html = (a[1].includes("str") ?
        decodeURIComponent(to) : to);
    return html;
}

function getHeaders(that) {
    const source = (that || this.source);
    var header = String(source.header);
    if (/^.?js(:|>)/.test(header)) {
        let h1 = header.split("js:"),
            h2 = header.split("js>");
        let head = (Array.isArray(h1) && h1[1]) || (Array.isArray(h2) && h2[1]);
        return String(head.toString());
    } else return header;
}

